--
-- Migration: **`attachments`**. A file attached to a plan, task, risk, proposal, idea, canvas item, budget line or scenario (LT-5). The bytes are an artifact; this row is the link, so removing an attachment (soft-delete) never loses the audit trail of what was attached.

CREATE TABLE IF NOT EXISTS "attachments" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "subject_kind" varchar NOT NULL, "subject_pid" uuid NOT NULL, "artifact_pid" uuid NOT NULL, "uploaded_by" varchar NULL, "deleted_at" timestamp with time zone NULL );

CREATE INDEX attachments_subject ON attachments (subject_kind, subject_pid) WHERE deleted_at IS NULL;
